var tijmenvangulik_powercurveadvisorexample;
(function (tijmenvangulik_powercurveadvisorexample) {
    class PowerCurveAdvisorExample extends ergometerWidgets.PowerCurveAdvisor {
        calcDiffs(data) {
            //here you can do more data processing or do a completaly differn procesing 
            super.calcDiffs(data);
        }
        makeAdvice() {
            //you can also use the curve data to make an advice _curveData
            //return an advice code, the widget speaks and shows its text (local.current().advisor_<code>)
            var advice = pm3.PowerCurveAdvice.none;
            //max diff is the greatest difference (negative is less positive is to much)
            if (Math.abs(this._maxDiff) >= this._giveAdviceAt) {
                if (this._maxDiff < 0) {
                    if (this._maxDiffPart == ergometerWidgets.StrokeParts.PART_LEGS) {
                        //not enough legs
                        advice = pm3.PowerCurveAdvice.useYourLegsMore;
                    }
                    else if (this._maxDiffPart == ergometerWidgets.StrokeParts.PART_TRUNK) {
                        //not enough trunk
                        advice = pm3.PowerCurveAdvice.moreTrunkAfterLegs;
                    }
                    else if (this._maxDiffPart == ergometerWidgets.StrokeParts.PART_ARMS) {
                        //not enough arms
                        //when trunk is also low then advice also about the trunk,
                        //because it is often an combination of these forces
                        if (this._trunkDiff < 0) {
                            advice = pm3.PowerCurveAdvice.more_trunk_and_arms_after_legs;
                        }
                        else
                            advice = pm3.PowerCurveAdvice.moreArmsAfterTrunk;
                    }
                }
                else if (this._maxDiff > 0) {
                    //to much of somthing often means there is not enough in another part or
                    //force the different parts is combined
                    if (this._maxDiffPart == ergometerWidgets.StrokeParts.PART_LEGS) {
                        //much legs but trunk and arms are both not enough
                        if (this._trunkDiff < this._armsDiff)
                            advice = pm3.PowerCurveAdvice.postpone_trunk; //the trunk part has the most les force, so blame the
                        else if (this._trunkDiff > this._armsDiff) //arms have most less force, blame the arms
                            advice = pm3.PowerCurveAdvice.postpone_arms;
                        else {
                            //it makes no sence to say that we should use less legs
                            //may be be force was all in the beginning,
                            advice = pm3.PowerCurveAdvice.more_trunk_and_arms_after_legs;
                        }
                    }
                    else if (this._maxDiffPart == ergometerWidgets.StrokeParts.PART_TRUNK) {
                        //this should not hapen often becausee this is the highest point in the curve and
                        //the curve is mapped arround the highest curve point.
                        //in this case the curve is more round on the top than configured, this is not
                        //allways a bad curve, but it reduces the peek force.
                        //maybe the the arms and the legs delivery too much in the
                        if (this._armsDiff < 0 && this._armsDiff < this._legsDiff) {
                            //when not much arms then advice to delay the arms so it will not be counted during the
                            //trunk part
                            advice = pm3.PowerCurveAdvice.postpone_arms;
                        }
                        else if (this._legsDiff < 0) {
                            //when not much legs then advice to accelrate the legs force, this
                            //should increase the legs peek force and make the curve less round
                            advice = pm3.PowerCurveAdvice.accelerate_legs;
                        }
                        else {
                            //not yet defined what to advice here
                            advice = pm3.PowerCurveAdvice.use_more_trunk;
                        }
                    }
                    else if (this._maxDiffPart == ergometerWidgets.StrokeParts.PART_ARMS) {
                        //too much force at the end
                        //when the trunk has not much force then the force of the trunk is too much at the
                        //at the same time as the legs
                        // when both legs and arms are low
                        if (this._legsDiff < 0 && this._legsDiff < this._trunkDiff) {
                            //more leg force to make compensate for the arm force
                            advice = pm3.PowerCurveAdvice.accelerate_legs;
                        }
                        else if (this._trunkDiff < 0) {
                            //there is less trunk so the trunk may be used during the arms because this is to high
                            advice = pm3.PowerCurveAdvice.trunk_earlier;
                        }
                        else
                            advice = pm3.PowerCurveAdvice.less_arms; //too much arm force (rowing is more about leg force)
                    }
                }
                else
                    advice = pm3.PowerCurveAdvice.greate_stroke;
            }
            else
                advice = pm3.PowerCurveAdvice.greate_stroke;
            return advice;
        }
        initControl() {
            super.initControl();
            this.labelText = "AdviceExample";
        }
        constructor(controller) {
            super(controller);
            this.caption = "Power curve example advisor";
            this.defaultWidth = 2;
        }
    }
    tijmenvangulik_powercurveadvisorexample.PowerCurveAdvisorExample = PowerCurveAdvisorExample;
    /*------------------------------------------------------------------------------
        Create and remove the widgets in the Plugin
    ------------------------------------------------------------------------------*/
    class ExamplePlugin extends ExternalPlugin {
        init() {
            //create the widget(s) on create
            dashboard.widgetRegistry().register(PowerCurveAdvisorExample, 'tijmenvangulik_examples_PowerCurveAdvisorExample', 'Advisor', ['Examples']);
        }
        remove() {
            //remove the widgets when the plugin is removed
            dashboard.widgetRegistry().deregister('tijmenvangulik_examples_PowerCurveAdvisorExample');
        }
    }
    var plugin;
    plugin = new ExamplePlugin();
})(tijmenvangulik_powercurveadvisorexample || (tijmenvangulik_powercurveadvisorexample = {}));

